# area: generics_variance
# hypothesis: A PEP 695 Handler[T] whose property setter takes Callable[[T], None] | None lets mypy and ty accept passing Handler[float] as Handler[int], so the stored callback fails at runtime.
from typing import Callable, reveal_type


class Handler[T]:
    def __init__(self, cb: Callable[[T], None]) -> None:
        self._cb: Callable[[T], None] | None = cb

    @property
    def cb(self) -> Callable[[T], None] | None:
        return self._cb

    @cb.setter
    def cb(self, value: Callable[[T], None] | None) -> None:
        self._cb = value

    def fire(self, item: T) -> None:
        if self._cb is not None:
            self._cb(item)


def use(h: Handler[int]) -> None:
    h.cb = lambda v: print(v.bit_length())


hf = Handler[float](lambda x: print(x.is_integer()))
reveal_type(hf)
hf.fire(2.0)


def run_last() -> None:
    try:
        use(hf)  # expect-error
        hf.fire(1.5)
    except AttributeError:
        print("AttributeError: float has no bit_length")


run_last()
